import{_ as a,C as s,o as n,c as d,j as e,a as o,E as l,a2 as i}from"./chunks/framework.B_GyVC5q.js";const k=JSON.parse('{"title":"Flows","description":"","frontmatter":{"title":"Flows"},"headers":[],"relativePath":"guide/flows.md","filePath":"guide/flows.md"}'),p={name:"guide/flows.md"};function c(g,t,h,u,f,m){const r=s("DocScreenshot");return n(),d("div",null,[t[0]||(t[0]=e("h1",{id:"flows",tabindex:"-1"},[o("Flows "),e("a",{class:"header-anchor",href:"#flows","aria-label":'Permalink to "Flows"'},"​")],-1)),t[1]||(t[1]=e("p",null,[e("strong",null,"Flows"),o(" is a visual canvas for building and running data and request pipelines against the connected 4D REST server. Wire blocks together, debug with breakpoints, and optionally let "),e("strong",null,"Flows AI"),o(" edit the graph with tools. See "),e("a",{href:"/4d-dataexplorer/guide/parts.html#flows"},"named parts"),o(".")],-1)),e("p",null,[l(r,{src:"/screenshots/43-flows.png",alt:"Flows canvas"})]),t[2]||(t[2]=i('<p>Open from:</p><ul><li>Status bar <strong>Flows</strong> control</li><li>Command palette (<strong>Flows</strong>)</li><li>Welcome screen <strong>Operators tour</strong> (loads a starter template)</li><li>Assistant navigation tools</li></ul><p>Flows are saved <strong>per database</strong> (<code>BASEID</code>) on this device. File-backed flows (desktop / mobile) keep only a path reference in that store; edits auto-save to the JSON file in a <a href="/4d-dataexplorer/guide/trusted-folders.html">trusted folder</a>.</p><h2 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h2><p>The editor has four areas:</p><table tabindex="0"><thead><tr><th>Area</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Library</strong></td><td>Saved flows for this database — search, duplicate, delete, clear all; import / export / copy JSON. On desktop and mobile, <strong>Open from trusted folder</strong> and <strong>Save to trusted folder</strong> use a file picker (folders + explorer, no preview pane) with a type filter (<strong>JSON</strong> or <strong>All files</strong>). File-backed flows keep only a path reference in the store; edits auto-save to the JSON file.</td></tr><tr><td><strong>Canvas</strong></td><td>Start and End anchors plus connected blocks; drag from the palette, drop on an edge to insert</td></tr><tr><td><strong>Outline / Nodes</strong></td><td>Search and multi-select blocks; add from the palette</td></tr><tr><td><strong>Dock</strong></td><td>Inspector, run log, and Flows AI — collapse or expand from the toolbar</td></tr></tbody></table><p>Double-click a block name (or use the pencil) to rename. Select a block or edge, then <strong>Delete</strong> / <strong>Backspace</strong> to remove it. <strong>Auto-organize</strong> lays the graph out.</p><p>File-backed flows show a drive icon. Open it for the path, <strong>Open in Files</strong>, and <strong>Reload</strong>. Removing a file-backed flow asks whether to unlink it from the library or also delete the JSON file. <strong>Clear all</strong> unlinks file-backed flows without deleting files.</p><p>Disable a block to skip it at run time (not available on <strong>Note</strong> blocks). Open <strong>Method</strong> and <strong>HTTP</strong> nodes in the <a href="/4d-dataexplorer/guide/method-executor.html">Method Executor</a> or <a href="/4d-dataexplorer/guide/http-client.html">HTTP Client</a> when you want the full request UI.</p><p>Operator tooltips (palette and canvas) include a <strong>RxJS documentation</strong> link for named operators; on desktop that opens in the system browser.</p><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>From an empty canvas or <strong>New flow</strong>, start with:</p><table tabindex="0"><thead><tr><th>Template</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Operators tour</strong></td><td>Map, filter, take — a stream pipeline with notes</td></tr><tr><td><strong>Operators · Combine</strong></td><td>ForkJoin two parallel branches into one array</td></tr><tr><td><strong>Operators · Accumulate</strong></td><td>Scan running totals vs Reduce a single sum</td></tr><tr><td><strong>Operators · Slice</strong></td><td>Distinct, skip, and take last</td></tr><tr><td><strong>Evaluate &amp; logic</strong></td><td>Set variables → evaluate → If true/false</td></tr><tr><td><strong>Query data</strong></td><td>Set vars → REST list + evaluate summary</td></tr><tr><td><strong>HTTP · Ping <code>$info</code></strong></td><td><code>GET /rest/$info</code> on the current server</td></tr><tr><td><strong>Trusted files</strong></td><td>List a trusted-folder alias (desktop / mobile)</td></tr></tbody></table><h2 id="blocks" tabindex="-1">Blocks <a class="header-anchor" href="#blocks" aria-label="Permalink to &quot;Blocks&quot;">​</a></h2><p>Palette categories:</p><table tabindex="0"><thead><tr><th>Category</th><th>Blocks</th></tr></thead><tbody><tr><td><strong>Inputs</strong></td><td>Inject (payload, including <code>$faker</code> numbers), Interval (<code>{ counter, timestamp }</code>), Timestamp</td></tr><tr><td><strong>Data</strong></td><td>List (one or more dataclasses), Create, Generate, Update, Purge (query / entity set / full dataclass), CSV import</td></tr><tr><td><strong>Network</strong></td><td>HTTP, Method (catalog / singleton / dataclass / entity)</td></tr><tr><td><strong>Code</strong></td><td>Set variables, Evaluate (sandboxed TypeScript <code>main()</code>), AI prompt</td></tr><tr><td><strong>Logic</strong></td><td>If, For, Repeat each, Delay</td></tr><tr><td><strong>Operators</strong></td><td>RxJS-style Map, Filter, Take, Merge, ForkJoin, Buffer, Debounce, and related operators</td></tr><tr><td><strong>Files</strong></td><td>File (<code>{{$files.alias}}</code> on desktop / mobile)</td></tr><tr><td><strong>Misc</strong></td><td>Start, End, Log, Timing timeline, Note (Markdown — skipped at run; cannot be disabled or take a breakpoint)</td></tr></tbody></table><p>Start and End are always present and cannot be removed. <strong>Inputs</strong> blocks are sources: they have no inbound port and fire when you run the flow (Interval keeps emitting until its count is reached or you stop).</p><p>Templated fields resolve <a href="/4d-dataexplorer/guide/environments.html">environment variables</a> at run time (<code>{{vars…}}</code>, <code>{{nodes.id.stdout}}</code>, <code>$faker</code>, <code>$this</code>, …). CSV imports support dataInit-style <code>$rel_*</code> relation columns, dependency-ordered waves, and optional skip-when-not-empty.</p><h2 id="generate-bulk-create" tabindex="-1">Generate (bulk create) <a class="header-anchor" href="#generate-bulk-create" aria-label="Permalink to &quot;Generate (bulk create)&quot;">​</a></h2><p><strong>Generate</strong> inserts many entities with the same field templates. <code>$faker</code> and <code>$pick</code> stay unresolved until <strong>each</strong> row is created, so names, addresses, and pictures differ across the batch (REST <code>createMany</code>, chunks of 100).</p><p>Use <strong>Create</strong> for a single row (or an explicit <code>entities</code> array). Prefer <strong>Generate</strong> when count is greater than 1.</p><h3 id="zip-foreign-keys" tabindex="-1">Zip foreign keys <a class="header-anchor" href="#zip-foreign-keys" aria-label="Permalink to &quot;Zip foreign keys&quot;">​</a></h3><p>On a Generate block, <strong>Zip from parent lists</strong> copies a sequential value onto each new row:</p><table tabindex="0"><thead><tr><th>Inspector field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Field (FK)</strong></td><td>Attribute on the new entity (for example <code>address</code> or <code>comp_id</code>)</td></tr><tr><td><strong>From path</strong></td><td>Binding to a previous result, usually <code>nodes.addr_hq.stdout.entities</code></td></tr><tr><td><strong>Parent attr</strong></td><td>Attribute to copy (default <code>ID</code>, with <code>__KEY</code> fallback)</td></tr></tbody></table><p>When zip is set, <strong>count</strong> follows that list length. Two zip columns must be the same length (for example staff addresses and repeated companies).</p><p>Wire <strong>one</strong> inbound edge into a Generate <code>in</code> port. Extra edges from an earlier parent (for example companies → staff addresses <strong>and</strong> Repeat each → staff addresses) overwrite the input: the last edge in the graph can run Generate <strong>before</strong> Repeat each finishes, so zip lists mismatch (often length 1 vs N).</p><p>Use zip when each parent must get a <strong>deterministic</strong> number of children. Use <code>{{$pick|from:ds.Parent.ID}}</code> only when a <strong>random</strong> FK from the pool is enough (counts per parent will be uneven).</p><h3 id="repeat-each" tabindex="-1">Repeat each <a class="header-anchor" href="#repeat-each" aria-label="Permalink to &quot;Repeat each&quot;">​</a></h3><p><strong>Repeat each</strong> (Logic palette) is CPU-only: it takes the inbound entity list (including a generate result’s <code>entities</code>) and emits a flattened list — each parent repeated N times. N can be a number or a template resolved <strong>per parent</strong>, for example <code>{{$faker.number.int | between:10,50}}</code>.</p><p>Typical seed:</p><ol><li><strong>Purge</strong> dependents first (one block, several dataclasses)</li><li>Generate parent rows (for example 100 addresses, then 100 companies <strong>zipped</strong> to those IDs)</li><li><strong>Repeat each</strong> on the companies</li><li>Generate child addresses with count <code>{{nodes.staff_slots.stdout.length}}</code></li><li>Generate children <strong>zipped</strong> to those addresses and the repeated company list</li></ol><p>Do <strong>not</strong> put Create/Generate on <code>for.item</code> for bulk inserts — that is one REST round trip per row.</p><h3 id="images-in-generate" tabindex="-1">Images in generate <a class="header-anchor" href="#images-in-generate" aria-label="Permalink to &quot;Images in generate&quot;">​</a></h3><p><code>{{$faker.company.logo}}</code> and <code>{{$faker.image.personPortrait}}</code> resolve to compact <strong>SVG data URIs</strong> (optional <code>| female</code> / <code>| male</code> on portraits). They do not download from a CDN before <code>$upload</code>, so large employee batches stay fast.</p><h2 id="run-and-debug" tabindex="-1">Run and debug <a class="header-anchor" href="#run-and-debug" aria-label="Permalink to &quot;Run and debug&quot;">​</a></h2><p>The run toolbar:</p><ul><li><strong>Run</strong> / <strong>Pause</strong> / <strong>Resume</strong> / <strong>Stop</strong></li><li><strong>Step over</strong></li><li><strong>Dry run</strong> and optional <strong>Verbose</strong></li><li>Per-block <strong>breakpoints</strong>, with a global enable/disable (step over still pauses). Notes cannot take a breakpoint</li><li><strong>Follow current step</strong> pans the canvas to the running block</li><li>Status bar <strong>Flows</strong> control expands with progress while a run is active</li></ul><p>The <strong>Log</strong> dock shows run output. Settings → <strong>Flow logs limit</strong> keeps the last N lines across runs (<code>0</code> = unlimited; you can still clear the log). <strong>Verbose</strong> logs each block as pending then done (or error), with duration next to the line, copy beside the text, and expandable Inputs / Outputs (same object tree as the <a href="/4d-dataexplorer/guide/console.html">Console</a>). A dry-run <strong>Summary</strong> row is collapsible and lists record counts grouped by action (create, update, delete, CSV import) then dataclass, plus CSV files, methods, and HTTP calls. <strong>Collapse all</strong> (next to Clear, or from the log context menu) folds expanded rows without clearing the log. At a breakpoint, add <strong>watches</strong> and evaluate expressions (<code>inputs.in</code>, <code>vars</code>, <code>nodes…</code>) in the run console.</p><p>REST traffic from HTTP / Method / data blocks appears in <a href="/4d-dataexplorer/guide/console.html">Console → Network</a>.</p><h3 id="run-on-server" tabindex="-1">Run on server <a class="header-anchor" href="#run-on-server" aria-label="Permalink to &quot;Run on server&quot;">​</a></h3><p>When the base exposes <code>FlowRunner</code> and the flow has no client-only nodes (CSV and File need the <a href="/4d-dataexplorer/guide/trusted-folders.html">desktop or mobile</a> app), <strong>Run on server</strong> executes on 4D instead of in the browser.</p><h2 id="flows-ai" tabindex="-1">Flows AI <a class="header-anchor" href="#flows-ai" aria-label="Permalink to &quot;Flows AI&quot;">​</a></h2><p>The <strong>AI</strong> dock tab <strong>builds optimized flows</strong> from a prompt and <strong>refactors</strong> the current graph with tools (instead of dumping JSON). It prefers batched <strong>generate</strong> (and <strong>zip</strong> / <strong>repeatEach</strong> for parent–child data) over per-row <code>for</code> + create. Configure an LLM in <a href="/4d-dataexplorer/guide/settings.html">Settings</a> — the same providers as the <a href="/4d-dataexplorer/guide/assistant.html">AI assistant</a>.</p><p>Starter prompts include adding a timing block, CSV + photos from trusted folders, <strong>optimize for speed</strong>, and simplifying a complicated graph.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/4d-dataexplorer/guide/environments.html">Environment variables</a> — templates inside block fields</li><li><a href="/4d-dataexplorer/guide/trusted-folders.html">Trusted folders</a> — File and CSV blocks</li><li><a href="/4d-dataexplorer/guide/http-client.html">HTTP Client</a> and <a href="/4d-dataexplorer/guide/method-executor.html">Method Executor</a> — open a node in the full editor</li><li><a href="/4d-dataexplorer/guide/assistant.html">AI assistant</a> — chat tools can open the Flows tab</li><li><a href="/4d-dataexplorer/guide/console.html">Console panel</a> — network log for flow HTTP</li></ul>',46))])}const w=a(p,[["render",c]]);export{k as __pageData,w as default};
